import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import styled from 'styled-components';
import { enableBedtimeMode, disableBedtimeMode, soundEffects } from '../services/mockApiService';
import { Howl } from 'howler';

// Styled components
const BedtimeModeContainer = styled.div`
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  background-color: ${props => props.theme.colors.bedtime};
  color: white;
  position: relative;
  overflow: hidden;
`;

const BackgroundOverlay = styled.div`
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 0, 0, 0.7);
  z-index: 0;
`;

const BackgroundImage = styled.div`
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-image: url('/images/night_sky.png');
  background-size: cover;
  background-position: center;
  opacity: 0.6;
  z-index: -1;
`;

const Header = styled.header`
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px;
  z-index: 1;
`;

const HeaderTitle = styled.h1`
  font-size: 24px;
  color: white;
  margin: 0;
`;

const BackButton = styled.button`
  background: none;
  border: none;
  font-size: 24px;
  color: white;
  cursor: pointer;

  &:hover {
    opacity: 0.8;
  }
`;

const MainContent = styled.main`
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 20px;
  z-index: 1;
`;

const MoonContainer = styled.div`
  width: 150px;
  height: 150px;
  margin-bottom: 30px;
  position: relative;
`;

const MoonImage = styled.img`
  width: 100%;
  height: 100%;
  object-fit: contain;
`;

const StarsAnimation = styled.div`
  position: absolute;
  top: -25px;
  left: -25px;
  right: -25px;
  bottom: -25px;

  .star {
    position: absolute;
    background-color: white;
    border-radius: 50%;
    animation: twinkle 2s infinite ease-in-out;
  }

  .star:nth-child(1) { top: 20%; left: 15%; width: 3px; height: 3px; animation-delay: 0s; }
  .star:nth-child(2) { top: 30%; left: 75%; width: 2px; height: 2px; animation-delay: 0.3s; }
  .star:nth-child(3) { top: 70%; left: 35%; width: 4px; height: 4px; animation-delay: 0.6s; }
  .star:nth-child(4) { top: 40%; left: 85%; width: 3px; height: 3px; animation-delay: 0.9s; }
  .star:nth-child(5) { top: 60%; left: 65%; width: 2px; height: 2px; animation-delay: 1.2s; }
  .star:nth-child(6) { top: 80%; left: 25%; width: 3px; height: 3px; animation-delay: 1.5s; }
  .star:nth-child(7) { top: 10%; left: 45%; width: 2px; height: 2px; animation-delay: 1.8s; }

  @keyframes twinkle {
    0% { opacity: 0.2; transform: scale(0.8); }
    50% { opacity: 1; transform: scale(1.2); }
    100% { opacity: 0.2; transform: scale(0.8); }
  }
`;

const SettingPanel = styled.div`
  background-color: rgba(255, 255, 255, 0.1);
  border-radius: 15px;
  padding: 20px;
  width: 100%;
  max-width: 500px;
  margin-bottom: 20px;
`;

const ToggleContainer = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
`;

const ToggleLabel = styled.span`
  font-size: 18px;
  font-weight: bold;
`;

const Switch = styled.label`
  position: relative;
  display: inline-block;
  width: 60px;
  height: 30px;

  input {
    opacity: 0;
    width: 0;
    height: 0;
  }

  span {
    position: absolute;
    cursor: pointer;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: #ccc;
    transition: .4s;
    border-radius: 30px;
  }

  span:before {
    position: absolute;
    content: "";
    height: 22px;
    width: 22px;
    left: 4px;
    bottom: 4px;
    background-color: white;
    transition: .4s;
    border-radius: 50%;
  }

  input:checked + span {
    background-color: ${props => props.theme.colors.secondary};
  }

  input:checked + span:before {
    transform: translateX(30px);
  }
`;

const SliderContainer = styled.div`
  margin-bottom: 20px;
`;

const SliderLabel = styled.div`
  font-size: 16px;
  margin-bottom: 10px;
`;

const SliderRow = styled.div`
  display: flex;
  align-items: center;
`;

const Slider = styled.input`
  flex: 1;
  margin-right: 10px;
`;

const SliderValue = styled.span`
  width: 60px;
  text-align: right;
`;

const TimerContainer = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  margin-top: 20px;
`;

const TimerLabel = styled.div`
  font-size: 16px;
  margin-bottom: 5px;
`;

const TimerValue = styled.div`
  font-size: 36px;
  font-weight: bold;
  margin-bottom: 10px;
`;

const VolumeIndicator = styled.div`
  background-color: rgba(94, 114, 235, 0.3);
  border-radius: 10px;
  padding: 8px 15px;
`;

const LullabyContainer = styled.div`
  width: 100%;
  max-width: 500px;
`;

const LullabyTitle = styled.div`
  font-size: 16px;
  margin-bottom: 15px;
`;

const LullabyOption = styled.div`
  display: flex;
  align-items: center;
  background-color: rgba(255, 255, 255, 0.05);
  border-radius: 10px;
  padding: 15px;
  margin-bottom: 10px;
  cursor: pointer;
  border: 1px solid transparent;
  transition: all 0.2s ease;

  ${props => props.selected && `
    background-color: rgba(94, 114, 235, 0.3);
    border-color: ${props.theme.colors.secondary};
  `}

  &:hover {
    background-color: rgba(255, 255, 255, 0.1);
  }
`;

const LullabyIcon = styled.div`
  width: 30px;
  height: 30px;
  margin-right: 15px;
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 20px;
`;

const LullabyText = styled.div`
  font-size: 16px;
`;

// Main component
const BedtimeMode = ({ settings, updateSettings, currentStory }) => {
  const navigate = useNavigate();
  const [isBedtimeEnabled, setIsBedtimeEnabled] = useState(false);
  const [fadeDuration, setFadeDuration] = useState(settings.bedtimeFadeDuration || 15);
  const [remainingTime, setRemainingTime] = useState(0);
  const [volume, setVolume] = useState(1);
  const [selectedLullaby, setSelectedLullaby] = useState('lullaby');

  // References for animations and sounds
  const timerRef = useRef(null);
  const fadeIntervalRef = useRef(null);
  const lullabySound = useRef(null);

  // Initialize lullaby sounds
  useEffect(() => {
    // Clean up on unmount
    return () => {
      if (lullabySound.current) {
        lullabySound.current.stop();
      }

      if (timerRef.current) {
        clearInterval(timerRef.current);
      }

      if (fadeIntervalRef.current) {
        clearInterval(fadeIntervalRef.current);
      }
    };
  }, []);

  // Toggle bedtime mode
  const toggleBedtimeMode = async () => {
    try {
      if (!isBedtimeEnabled) {
        // Enable bedtime mode
        const result = await enableBedtimeMode(fadeDuration);

        if (result.success) {
          setIsBedtimeEnabled(true);
          startBedtimeMode();
        }
      } else {
        // Disable bedtime mode
        const result = await disableBedtimeMode();

        if (result.success) {
          setIsBedtimeEnabled(false);
          stopBedtimeMode();
        }
      }
    } catch (error) {
      console.error('Error toggling bedtime mode:', error);
    }
  };

  // Start bedtime mode
  const startBedtimeMode = () => {
    // Set initial values
    const totalSeconds = fadeDuration * 60;
    setRemainingTime(totalSeconds);
    setVolume(1);

    // Start countdown timer
    timerRef.current = setInterval(() => {
      setRemainingTime(prev => {
        if (prev <= 1) {
          clearInterval(timerRef.current);
          playLullaby();
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    // Start volume fade
    const fadeStepTime = 1000; // Update volume every second
    const fadeStep = 1 / (totalSeconds); // Volume reduction per step

    fadeIntervalRef.current = setInterval(() => {
      setVolume(prev => {
        const newVolume = Math.max(0, prev - fadeStep);

        // If volume reaches 0, clear the interval
        if (newVolume <= 0) {
          clearInterval(fadeIntervalRef.current);
        }

        return newVolume;
      });
    }, fadeStepTime);
  };

  // Stop bedtime mode
  const stopBedtimeMode = () => {
    // Clear timers
    if (timerRef.current) {
      clearInterval(timerRef.current);
    }

    if (fadeIntervalRef.current) {
      clearInterval(fadeIntervalRef.current);
    }

    // Stop lullaby if playing
    if (lullabySound.current) {
      lullabySound.current.stop();
    }

    // Reset values
    setRemainingTime(0);
    setVolume(1);
  };

  // Play selected lullaby
  const playLullaby = () => {
    // Stop any currently playing lullaby
    if (lullabySound.current) {
      lullabySound.current.stop();
    }

    // Get the sound URL based on selection
    let soundUrl;
    switch (selectedLullaby) {
      case 'lullaby':
        soundUrl = soundEffects.lullaby;
        break;
      case 'white_noise':
        soundUrl = soundEffects.white_noise;
        break;
      case 'silence':
      default:
        return; // Don't play anything for silence
    }

    // Create and play the sound
    lullabySound.current = new Howl({
      src: [soundUrl],
      loop: true,
      volume: 0.5,
      autoplay: true
    });
  };

  // Format remaining time as MM:SS
  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  // Navigate back to story screen
  const goToStoryScreen = () => {
    navigate('/');
  };

  // Update app settings when fade duration changes
  const handleFadeDurationChange = (value) => {
    setFadeDuration(value);

    // Update app settings
    if (updateSettings) {
      updateSettings({
        bedtimeFadeDuration: value
      });
    }
  };

  return (
    <BedtimeModeContainer>
      <BackgroundOverlay />
      <BackgroundImage />

      <Header>
        <BackButton onClick={goToStoryScreen}>←</BackButton>
        <HeaderTitle>Bedtime Mode</HeaderTitle>
      </Header>

      <MainContent>
        <MoonContainer>
          <MoonImage src="/images/moon.png" alt="Moon" />
          {isBedtimeEnabled && (
            <StarsAnimation>
              <div className="star"></div>
              <div className="star"></div>
              <div className="star"></div>
              <div className="star"></div>
              <div className="star"></div>
              <div className="star"></div>
              <div className="star"></div>
            </StarsAnimation>
          )}
        </MoonContainer>

        <SettingPanel>
          <ToggleContainer>
            <ToggleLabel>Bedtime Mode</ToggleLabel>
            <Switch>
              <input
                type="checkbox"
                checked={isBedtimeEnabled}
                onChange={toggleBedtimeMode}
              />
              <span></span>
            </Switch>
          </ToggleContainer>

          <SliderContainer>
            <SliderLabel>Fade Duration</SliderLabel>
            <SliderRow>
              <Slider
                type="range"
                min="5"
                max="30"
                step="5"
                value={fadeDuration}
                onChange={(e) => handleFadeDurationChange(parseInt(e.target.value))}
                disabled={isBedtimeEnabled}
              />
              <SliderValue>{fadeDuration} min</SliderValue>
            </SliderRow>
          </SliderContainer>

          {isBedtimeEnabled && (
            <TimerContainer>
              <TimerLabel>Time Remaining</TimerLabel>
              <TimerValue>{formatTime(remainingTime)}</TimerValue>
              <VolumeIndicator>
                Volume: {Math.round(volume * 100)}%
              </VolumeIndicator>
            </TimerContainer>
          )}
        </SettingPanel>

        <LullabyContainer>
          <LullabyTitle>After Story Ends</LullabyTitle>

          <LullabyOption 
            selected={selectedLullaby === 'lullaby'}
            onClick={() => setSelectedLullaby('lullaby')}
          >
            <LullabyIcon>🎵</LullabyIcon>
            <LullabyText>Lullaby</LullabyText>
          </LullabyOption>

          <LullabyOption 
            selected={selectedLullaby === 'white_noise'}
            onClick={() => setSelectedLullaby('white_noise')}
          >
            <LullabyIcon>🌊</LullabyIcon>
            <LullabyText>White Noise</LullabyText>
          </LullabyOption>

          <LullabyOption 
            selected={selectedLullaby === 'silence'}
            onClick={() => setSelectedLullaby('silence')}
          >
            <LullabyIcon>🔇</LullabyIcon>
            <LullabyText>Silence</LullabyText>
          </LullabyOption>
        </LullabyContainer>
      </MainContent>
    </BedtimeModeContainer>
  );
};

export default BedtimeMode;
